node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// SQLite files start with 'SQLite format 3'
console.log('Header:', buf.slice(0, 16).toString());
console.log('File size:', buf.length);
// Search for table names - look for CREATE TABLE statements
const text = buf.toString('latin1');
const matches = text.match(/CREATE TABLE[^;]*/g);
if (matches) matches.forEach(m => console.log(m.trim()));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const rows = db.prepare('SELECT * FROM ts_contacts').all();
console.log(JSON.stringify(rows, null, 2));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('world.db');

// 1. Check cellular service is enabled
const settings = db.prepare('SELECT cellular FROM ts_device_settings').get();
console.log('Cellular enabled:', settings.cellular);

// 2. Get self contact (sender)
const self = db.prepare('SELECT person_id, phone_number FROM ts_contacts WHERE is_self = 1').get();
console.log('Sender:', self);

// 3. Get recipient by phone number
const recipient = db.prepare('SELECT person_id FROM ts_contacts WHERE phone_number = ?').get('+1-312-555-0172');
console.log('Recipient:', recipient);

// 4. Insert message
const messageId = crypto.randomUUID();
const now = Date.now() / 1000;
db.prepare(
  'INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)'
).run(messageId, self.person_id, self.phone_number, recipient ? recipient.person_id : null, '+1-312-555-0172', 'Test message from Emily Carter.', now);

console.log('Message sent! ID:', messageId);

// 5. Verify
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(messageId);
console.log('Stored message:', msg);
"
